def covariance_from_scale_tril(
    scale_tril: torch.Tensor,
) -> torch.Tensor:
    if scale_tril.shape[-2:] != (
        POSITION_DIM,
        POSITION_DIM,
    ):
        raise ValueError(
            "scale_tril must end "
            "in [3,3]."
        )

    return (
        scale_tril
        @
        scale_tril.transpose(
            -1,
            -2,
        )
    )

def gaussian_nll_per_horizon(
    mean: torch.Tensor,
    scale_tril: torch.Tensor,
    target: torch.Tensor,
) -> torch.Tensor:
    """
    Full 3-D Gaussian negative log likelihood.

    Returns:
        [B,H]
    """

    if mean.shape != target.shape:
        raise ValueError(
            "Gaussian mean/target "
            "shape mismatch."
        )

    if mean.ndim != 3:
        raise ValueError(
            "mean and target must "
            "be [B,H,3]."
        )

    if mean.shape[-1] != (
        POSITION_DIM
    ):
        raise ValueError(
            "Expected 3-D trajectory."
        )

    if scale_tril.shape != (
        mean.shape[0],
        mean.shape[1],
        POSITION_DIM,
        POSITION_DIM,
    ):
        raise ValueError(
            "scale_tril shape mismatch."
        )

def masked_gaussian_nll(
    mean: torch.Tensor,
    scale_tril: torch.Tensor,
    target: torch.Tensor,
    validity_mask: torch.Tensor,
) -> torch.Tensor:
    nll = (
        gaussian_nll_per_horizon(
            mean,
            scale_tril,
            target,
        )
    )

    if validity_mask.shape != (
        nll.shape
    ):
        raise ValueError(
            "Gaussian validity-mask "
            "shape mismatch."
        )

    mask = validity_mask.to(
        dtype=nll.dtype
    )

    denominator = (
        mask.sum()
    )

    if denominator.item() == 0:
        return (
            mean.sum()
            *
            0.0
            +
            scale_tril.sum()
            *
            0.0
        )
